// db.js — a pretend "slow" product database.
// It stands in for a real SQL/NoSQL store. The 150 ms delay simulates a slow
// query, which is why we put a Redis cache in front of it.
// This is already written for you. Do NOT edit this file.

const PRODUCTS = {
  "1": { id: "1", name: "Wireless Mouse", price: 799 },
  "2": { id: "2", name: "Mechanical Keyboard", price: 2499 },
  "3": { id: "3", name: "USB-C Hub", price: 1299 },
  "4": { id: "4", name: "Laptop Stand", price: 999 },
  "5": { id: "5", name: "1080p Webcam", price: 1799 },
};

// Simulates a slow database read. Returns the product, or null if not found.
export async function findProductInDB(productId) {
  await new Promise((resolve) => setTimeout(resolve, 150)); // slow query
  return PRODUCTS[productId] || null;
}
